        void paintPatch(System.Windows.Shapes.Rectangle rTaxel, bool bValid, uint uiChannel)
        {
            if (bValid) rTaxel.Fill = Gradient(SDDRawData[uiChannel]);// - iaBiasTaxelValues[uiBoard, uiADC, uiChannel]);
            else rTaxel.Fill = new SolidColorBrush { Color = Color.FromArgb(255, 150, 150, 150) };
        }

        // color-code the input range of 0 to 4095 into beautiful color gradient
        SolidColorBrush Gradient(int iTexelValue)
        {
            // Gain of 2
            iTexelValue = (int)(fOUTPUTGAINFACTOR * iTexelValue);

            // Limit the input between 0 and 4095
            iTexelValue = Math.Max(0, iTexelValue);
            iTexelValue = Math.Min(4095, iTexelValue);

            SolidColorBrush mySolidColorBrush = new SolidColorBrush();

            // Dark green to light green (0,50,0 -> 0,255,0)
            if (iTexelValue < 1366) mySolidColorBrush.Color = Color.FromArgb(255, 0, Math.Min((byte)255, (byte)(50 + (iTexelValue / 6.65))), 0);
            // Light green to yellow (0,255,0 -> 255,255,0)
            else
            if (iTexelValue < 2731) mySolidColorBrush.Color = Color.FromArgb(255, Math.Min((byte)255, (byte)((iTexelValue - 1365) / 5.35)), 255, 0);
            // Yellow to red (255,255,0 -> 255,0,0)
            else mySolidColorBrush.Color = Color.FromArgb(255, 255, Math.Min((byte)255, (byte)(255 - ((iTexelValue - 1365) / 5.35))), 0);

            return (mySolidColorBrush);
        }
    }
